/* v103 — matched process media, clear package list and expandable event price */
.process-duration-card{aspect-ratio:16/9;display:flex;flex-direction:column;justify-content:flex-end;align-items:flex-start;padding:clamp(24px,4vw,48px);margin-bottom:18px;overflow:hidden;background:linear-gradient(145deg,#f7f9fa 0%,#e7ecee 100%);border:1px solid #d5dde0;position:relative}
.process-duration-card:before{content:"";position:absolute;width:46%;aspect-ratio:1;border:1px solid #c7d0d4;border-radius:50%;right:-8%;top:-34%;opacity:.75}
.process-duration-card>span{position:relative;font-size:9px;letter-spacing:.18em;color:#738087}
.process-duration-card>strong{position:relative;margin:12px 0 7px;font:500 clamp(34px,5vw,58px)/1.05 var(--font-heading);letter-spacing:-.055em;color:#273236}
.process-duration-card>small{position:relative;font-size:11px;color:#69757b}
.process-type-tabs button{justify-content:center;text-align:center}
.process-type-tabs strong{font-size:18px}
.ratio-buttons button{position:relative;display:grid;place-items:center;gap:3px;min-height:61px;padding:10px}
.ratio-buttons button>span{font-size:18px}
.ratio-buttons button>small{font-size:8px;line-height:1;color:#7b878c;letter-spacing:.02em;white-space:nowrap}
.ratio-buttons button[aria-pressed=true]>small{color:#39464c}
.package-section>h2{margin-bottom:9px}
.package-section>p{color:var(--muted)}
.package-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0;border-top:1px solid var(--line)}
.package-list li{display:grid;grid-template-columns:20px minmax(0,1fr);gap:10px;align-items:start;padding:14px 4px;background:transparent;border-bottom:1px solid var(--line);font-size:13px;font-weight:500;color:#354047}
.package-list li>span:first-child{width:17px;height:17px;display:grid;place-items:center;border:1px solid #acb8bd;border-radius:50%;color:#66767d;font-size:9px;margin-top:1px}
.event-benefits{border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:44px}
.event-benefits>summary{list-style:none;display:flex;align-items:center;justify-content:space-between;gap:25px;padding:25px 4px;cursor:pointer}
.event-benefits>summary::-webkit-details-marker{display:none}
.event-benefits>summary span{display:grid;gap:5px}
.event-benefits>summary small{font-size:10px;color:#748188;letter-spacing:.04em}
.event-benefits>summary strong{font-size:24px;font-weight:500;color:var(--ink)}
.event-benefits>summary>b{width:38px;height:38px;display:grid;place-items:center;border:1px solid #bdc6ca;font-size:20px;font-weight:400;transition:transform .25s ease}
.event-benefits[open]>summary>b{transform:rotate(45deg)}
.event-benefits-body{padding:5px 4px 34px}
.event-benefits-body>p{margin-bottom:12px;color:var(--muted);font-size:13px}
.booking-checkout{position:sticky;top:calc(var(--header) + 16px);max-height:calc(100dvh - var(--header) - 32px);overflow:auto;overscroll-behavior:contain;scrollbar-width:thin}
