@keyframes arCompareIn{to{opacity:1;transform:translateY(0)}}
/* 각 비교 기준을 독립된 행으로 세로 배치, 행 안에서는 일반 제작/WISTIA 2열만 사용
   (기존 3열 그리드 + 절대배치 WISTIA 패널 구조를 완전히 제거) */
.ar-compare-list{display:flex;flex-direction:column;min-width:0}
.ar-compare-row{padding:20px 0;border-top:1px solid var(--line);cursor:pointer;min-width:0;box-sizing:border-box;opacity:0;transform:translateY(8px)}
.ar-compare-row:first-child{border-top:0;padding-top:0}
.ar-compare.is-visible .ar-compare-row{animation:arCompareIn .4s ease-out forwards;animation-delay:calc(.2s + var(--row-i) * .14s)}
.ar-compare-criteria{display:flex;align-items:baseline;gap:8px;margin-bottom:12px}
.ar-compare-index{font-size:10px;letter-spacing:.08em;color:var(--silver);font-weight:600}
.ar-compare-criteria strong{font-size:14px;font-weight:600;color:var(--ink)}
.ar-compare-cells{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px;min-width:0}
.ar-compare-cell{min-width:0;box-sizing:border-box;padding:14px 14px;border-radius:8px;display:flex;flex-direction:column;gap:6px}
.ar-compare-cell-label{font-size:10.5px;font-weight:600;letter-spacing:.04em;color:var(--silver)}
.ar-compare-cell-value{font-size:13px;line-height:1.5;word-break:keep-all}
.ar-compare-general{background:transparent}
.ar-compare-general .ar-compare-cell-value{color:var(--muted)}
.ar-compare-wistia{background:#fff;border:1px solid var(--line);box-shadow:0 1px 2px #1c232808}
.ar-compare-wistia .ar-compare-cell-label{color:#8b9296}
.ar-compare-wistia .ar-compare-cell-value{color:var(--ink);font-weight:700;position:relative;display:inline-flex;align-items:center;gap:6px}
.ar-compare-arrow{opacity:0;font-size:12px;color:var(--silver);transition:opacity .2s ease-out}
.ar-compare-row.is-focused .ar-compare-wistia{background:linear-gradient(135deg,#ffffff,#f4f5f6)}
.ar-compare-row.is-focused .ar-compare-arrow{opacity:1}
.ar-compare-row.is-dimmed{opacity:.5}
.ar-compare-row:focus-visible{outline:2px solid #526b7a;outline-offset:3px;border-radius:6px}
.ar-compare-note{margin:20px 0 0;font-size:12px;line-height:1.6;color:var(--silver)}
@container solo-detail (max-width:300px){
 .ar-compare-cells{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){
 .ar-compare-title,.ar-compare-row{opacity:1;transform:none;animation:none}
}

/* 이 페이지는 PC에서도 실제 콘텐츠 폭이 ~500px 모바일 캔버스로 고정되므로,
   내부 섹션은 뷰포트 min-width가 아니라 이 컨테이너의 실제 inline 크기를 기준으로 반응한다 */
.solo-detail-scope{container-type:inline-size;container-name:solo-detail;min-width:0}
.solo-detail-scope .ar-expert-story{padding-top:56px;padding-bottom:64px}

/* 진행 과정 아코디언 — 카드 제목 18~21px 범위로 */
.solo-detail-scope .process-accordion summary h3{font-size:19px;line-height:1.4}
.solo-detail-scope .process-accordion-body>p{font-size:14px;line-height:1.8}

/* 실제 고객 후기 / 진행 과정 / 타사 비교 / FAQ 섹션 제목 — 일반 섹션 제목 26~30px 범위 */
.solo-detail-scope .section-heading h2{font-size:clamp(22px,5.8vw,26px);line-height:1.4;letter-spacing:-.02em}
.solo-detail-scope .section-heading div>p{font-size:14px;line-height:1.7;margin-top:10px}

/* AR 비율 선택 영역 상하 여백 정리 */
.solo-detail-scope .ratio-section{padding-block:56px}
.solo-detail-scope .ratio-explainer{padding-block:28px}

/* FAQ 전후 여백, 본문 크기 */
.solo-detail-scope .worry-section{padding-top:56px;padding-bottom:56px}
.solo-detail-scope .faq-list summary{font-size:16px}
.solo-detail-scope .faq-list details>p{font-size:14px;line-height:1.8}

/* 4) 타사 비교표 — 기존 파란색 톤을 걷어내고 화이트·실버·잉크 톤으로 재구성,
   3열 표 대신 세로 카드형 리스트로 바꿔 500px 캔버스 안에서도 13~14px 이상을 유지합니다 */
.solo-detail-scope .comparison-band{background:var(--wash)}
.solo-detail-scope .comparison-table{border:1px solid var(--line);border-radius:8px;background:#fff}
.solo-detail-scope .comparison-head{display:none}
.solo-detail-scope .comparison-row{display:grid;grid-template-columns:1fr;gap:6px;padding:18px 18px;border-top:1px solid var(--line)}
.solo-detail-scope .comparison-row:first-child{border-top:0}
.solo-detail-scope .comparison-row>strong{background:none;padding:0;font-size:15px;font-weight:600;color:var(--ink)}
.solo-detail-scope .comparison-row>span{display:block;min-width:0;padding:10px 12px;font-size:14px;line-height:1.6;border:0;border-radius:5px}
.solo-detail-scope .comparison-row>span:first-of-type{margin-top:2px;background:var(--wash);color:var(--muted)}
.solo-detail-scope .comparison-row>span:last-child{margin-top:0;background:#25292b0f;color:var(--ink);font-weight:600;border-left:3px solid var(--ink)}
.solo-detail-scope .comparison-row small{display:block;margin-bottom:3px;font-size:11px;font-weight:500;letter-spacing:.03em;color:var(--silver)}
.solo-detail-scope .comparison-note{font-size:12px;line-height:1.7}

/* 5) PC 외부 배경 — 실버 화이트 + 미세 그레인 + 비대칭 확산광 (v154, 정지·문자 없음) */
@media(min-width:780px){
 body.is-solo-detail{position:relative;background:linear-gradient(165deg,#fbfbfa 0%,#f7f6f3 38%,#eef0f2 72%,#e9ebed 100%)}
 body.is-solo-detail:before{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;background:
   radial-gradient(60% 46% at 82% 88%,#f3f1ec9c 0%,transparent 68%),
   radial-gradient(46% 38% at 8% 12%,#eef1f395 0%,transparent 70%)}
 body.is-solo-detail:after{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;opacity:.035;mix-blend-mode:multiply;
   background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
   background-size:120px 120px}
 body.is-solo-detail main{position:relative;z-index:1;box-shadow:0 30px 70px -40px #1c232808,0 8px 24px -12px #1c23280a}
 body.is-solo-detail #siteHeader{position:sticky;z-index:1}
}

/* 6) PC 우측 하단 2단 플로팅 CTA — #soloDesktopCta (v156, 최상위 포털 배치 + 확대 리사이즈) */
.solo-desktop-cta{display:none}
@media(min-width:780px){
 body.is-solo-detail #floatingKakao,body.is-solo-detail .fixed-price{display:none}
 .solo-desktop-cta{display:flex;flex-direction:column;gap:10px;position:fixed;right:max(40px,calc(env(safe-area-inset-right) + 24px));bottom:max(40px,calc(env(safe-area-inset-bottom) + 24px));z-index:60}
 .solo-desktop-cta a{position:relative;display:grid;grid-template-columns:20px 1fr 16px;align-items:center;gap:11px;height:48px;width:158px;padding:0 15px;border-radius:14px;overflow:hidden;white-space:nowrap;transition:width .2s ease-out,background-color .2s ease-out;box-shadow:0 4px 10px -4px #1c23281f,0 16px 30px -14px #1c232838}
 .solo-desktop-cta:hover a,.solo-desktop-cta:focus-within a{width:276px}
 .solo-desktop-cta-price{background:#202426;color:#fff}
 .solo-desktop-cta-kakao{background:#fbfaf7;color:#25292b;border:1px solid #d9dcdd}
 .solo-desktop-cta .cta-icon{display:flex;align-items:center;justify-content:center;width:20px;height:20px;line-height:0}
 .solo-desktop-cta .cta-icon svg{display:block;width:20px;height:20px}
 .solo-desktop-cta-kakao .cta-icon svg{filter:none}
 .solo-desktop-cta .cta-label{position:relative;min-width:0;height:16px;overflow:hidden}
 .solo-desktop-cta .cta-label b{position:absolute;left:0;top:0;font-weight:600;font-size:13.5px;line-height:16px;white-space:nowrap;transition:opacity .18s ease-out}
 .solo-desktop-cta .cta-short{position:static;opacity:1;transition-delay:.06s;text-transform:uppercase;letter-spacing:.07em;font-size:12.5px}
 .solo-desktop-cta .cta-full{opacity:0}
 .solo-desktop-cta:hover .cta-short,.solo-desktop-cta:focus-within .cta-short{position:absolute;opacity:0;transition-delay:0s}
 .solo-desktop-cta:hover .cta-full,.solo-desktop-cta:focus-within .cta-full{position:static;opacity:1;transition-delay:.09s}
 .solo-desktop-cta .cta-arrow{display:flex;align-items:center;justify-content:flex-end;font-size:16px;line-height:1;opacity:.7}
 .solo-desktop-cta a:focus-visible{outline:2px solid #526b7a;outline-offset:3px}
}

/* 7) HERO 하단 아치형 곡선(심화) + 진입 애니메이션 (v156) */
.ar-hook-hero{border-radius:0 0 50% 50%/0 0 40px 40px}
.solo-detail-scope .ar-hook-copy{padding-bottom:calc(40px + 40px)}
@media(min-width:780px){.ar-hook-copy{padding-bottom:calc(56px + 40px)}}
.ar-hook-copy .eyebrow{display:inline-block;padding:6px 14px;border-radius:999px;background:#ffffffd9;border:1px solid #ffffff66;color:var(--ink);opacity:1;font-size:11px;letter-spacing:.12em}
.ar-hook-video-control{position:absolute;top:24px;right:28px;z-index:3;display:flex;align-items:center;justify-content:center;width:44px;height:44px;min-width:44px;min-height:44px;padding:0;border:0;border-radius:50%;background:transparent;color:#fff;opacity:.9;transition:opacity .15s ease-out,background-color .15s ease-out}
.ar-hook-video-control:hover,.ar-hook-video-control:focus-visible{opacity:1;background:#ffffff1f}
.ar-hook-video-control .ar-icon-play,.ar-hook-video-control .ar-icon-pause{display:flex;align-items:center;justify-content:center;width:17px;height:17px}
.ar-hook-video-control .ar-icon-pause{display:none}
.ar-hook-video-control.is-playing .ar-icon-play{display:none}
.ar-hook-video-control.is-playing .ar-icon-pause{display:flex}
.ar-hook-video-control:focus-visible{outline:2px solid #fff;outline-offset:2px}

/* ============ WISTIA 최종 UI 업데이트 (v159) ============ */

/* 1) 상단 고정 가격 CTA — 헤더 바로 아래 sticky */
.solo-top-cta-sentinel{display:block;height:0}
.solo-top-cta{position:sticky;top:var(--header);z-index:30;background:#1c2022;transition:box-shadow .2s ease-out}
.solo-top-cta.is-stuck{box-shadow:0 1px 0 #00000014,0 6px 14px -10px #00000024}
.solo-top-cta a{display:flex;align-items:center;justify-content:center;gap:8px;min-height:52px;padding:8px 16px;color:#fff;font-size:13.5px;font-weight:500;letter-spacing:-.01em;text-align:center}
.solo-top-cta a b{font-weight:500;line-height:1}
.solo-top-cta a:focus-visible{outline:2px solid #fff;outline-offset:-3px}
@media(max-width:360px){.solo-top-cta a{font-size:12.5px;gap:6px}}

/* 2) 1인·2인 선택 UI — 상품명 + 설명 위계, 탭 인디케이터 */
.solo-person-picker{padding:0}
.solo-person-tabs{position:relative;display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line)}
.solo-person-tab{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-height:64px;padding:14px 8px;color:var(--muted);text-decoration:none;transition:background-color .15s ease-out}
.solo-person-tab+.solo-person-tab{border-left:1px solid var(--line)}
.solo-person-tab strong{font-size:15px;font-weight:500;color:inherit;letter-spacing:-.01em}
.solo-person-tab span{font-size:11.5px;color:inherit;opacity:.82}
.solo-person-tab.is-active{background:#f4f5f5;color:var(--ink)}
.solo-person-tab.is-active strong{font-weight:700}
@media(hover:hover){.solo-person-tab:not(.is-active):hover{background:#f8f9f9}}
.solo-person-tab:focus-visible{outline:2px solid #526b7a;outline-offset:-2px}
.solo-person-indicator{position:absolute;bottom:-1px;left:0;width:50%;height:2px;background:var(--ink);transform:translateX(0);transition:transform .22s ease-out}
.solo-person-tabs[data-active="1"] .solo-person-indicator{transform:translateX(100%)}
@media(prefers-reduced-motion:reduce){.solo-person-indicator{transition:none}}

/* 3) 전문가 스토리 — 2분할 확장 패널 */
.solo-detail-scope .ar-expert-split{position:relative;display:grid;grid-template-columns:35fr 65fr;gap:0;border-radius:17px;overflow:hidden;height:clamp(340px,84cqw,380px);min-width:0;box-sizing:border-box;transition:grid-template-columns .4s cubic-bezier(.4,0,.2,1)}
.solo-detail-scope .ar-expert-split[data-active="0"]{grid-template-columns:65fr 35fr}
.solo-detail-scope .ar-expert-split.is-single{display:block}
.solo-detail-scope .ar-expert-split.is-single .ar-expert-panel{width:100%;height:100%;cursor:default}
.ar-expert-panel{position:relative;display:block;min-width:0;border:0;padding:0;margin:0;background:none;cursor:pointer;text-align:left;overflow:hidden}
.ar-expert-panel-media{position:absolute;inset:0;z-index:0}
.ar-expert-panel-media img{width:100%;height:100%;object-fit:cover;object-position:center 22%;filter:saturate(.94) brightness(.98);transition:filter .4s ease-out}
.ar-expert-panel[data-expert-panel="1"] .ar-expert-panel-media img{object-position:center 30%}
.ar-expert-panel.is-active .ar-expert-panel-media img{filter:saturate(1.04) brightness(1.02)}
.ar-expert-panel-overlay{position:absolute;inset:0;z-index:1;background:linear-gradient(180deg,#1c2022b3 0%,#1c202273 42%,#1c2022cc 100%);opacity:1;transition:opacity .4s ease-out,background .4s ease-out}
.ar-expert-panel.is-active .ar-expert-panel-overlay{background:linear-gradient(to top,rgba(8,10,11,.88) 0%,rgba(8,10,11,.62) 35%,rgba(8,10,11,.18) 72%,transparent 100%)}
.ar-expert-panel-toggle{position:absolute;top:14px;right:14px;z-index:3;display:flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;background:#ffffffe6;color:#1c2022;font-size:15px;line-height:1}
.ar-expert-panel-content{position:absolute;left:20px;right:20px;bottom:20px;z-index:2;display:flex;flex-direction:column;gap:4px;color:#fff;text-shadow:0 1px 8px rgba(0,0,0,.25)}
.ar-expert-panel-index{font-size:10px;letter-spacing:.06em;color:#fff;opacity:.8}
.ar-expert-panel-keyword{font-size:15px;font-weight:700;letter-spacing:-.01em;color:#fff}
.ar-expert-panel-sub{font-size:11.5px;color:#fff;opacity:0;max-height:0;overflow:hidden;transition:opacity .22s ease-out}
.ar-expert-panel.is-active .ar-expert-panel-sub{opacity:.82}
.ar-expert-panel-detail{display:block;font-size:12px;line-height:1.7;color:#fff;opacity:0;max-height:0;overflow:hidden;transition:opacity .22s ease-out}
.ar-expert-panel.is-active .ar-expert-panel-detail{opacity:.86;max-height:200px;transition-delay:.18s}
.ar-expert-panel.is-active .ar-expert-panel-sub{max-height:60px;transition-delay:.18s}
.ar-expert-panel:not(.is-active) .ar-expert-panel-sub,.ar-expert-panel:not(.is-active) .ar-expert-panel-detail{transition-delay:0s}
.ar-expert-panel:focus-visible{outline:2px solid #fff;outline-offset:-3px}
.ar-expert-hint{margin:14px 0 0;font-size:12px;color:var(--silver);text-align:center}
@media(prefers-reduced-motion:reduce){
 .solo-detail-scope .ar-expert-split,.ar-expert-panel-media img,.ar-expert-panel-overlay,.ar-expert-panel-sub,.ar-expert-panel-detail{transition:none}
}

/* 4) AR 비율 체험 UI 전면 개선 (solo 전용, 기존 arRatio()·switchRatioAudio 로직 재사용) */
.solo-ratio{transition:background .7s ease;background:linear-gradient(180deg,#ffffff,#f7f8f8)}
.solo-ratio[data-ratio="50"]{background:linear-gradient(180deg,#ffffff,#eef0f0)}
.solo-ratio[data-ratio="70"]{background:radial-gradient(120% 100% at 50% 0%,#ffffff,#eceeee 60%,#e6e8e9)}
.solo-ratio[data-ratio="100"]{background:linear-gradient(180deg,#eef0f0,#dfe2e3)}
.solo-ratio-panel{max-width:420px;margin:0 auto;display:flex;flex-direction:column;align-items:center;text-align:center;padding-top:8px}
.solo-ratio-center{position:relative;display:flex;flex-direction:column;align-items:center;gap:4px;padding:18px 0 8px;transition:opacity .16s ease-out}
.solo-ratio-center.is-fading{opacity:0}
.solo-ratio-glow{position:absolute;top:-10px;left:50%;width:220px;height:220px;transform:translateX(-50%);border-radius:50%;background:radial-gradient(circle,#ffffff 0%,#eceeee 55%,transparent 76%);z-index:0}
.solo-ratio-value{position:relative;z-index:1;display:flex;align-items:baseline;font-weight:400;letter-spacing:-.05em;color:var(--ink);line-height:1}
.solo-ratio-value .solo-ratio-num{font-size:clamp(56px,16vw,76px)}
.solo-ratio-value small{font-size:22px;margin-left:4px;font-weight:400}
.solo-ratio-label{position:relative;z-index:1;font-size:15px;font-weight:600;color:var(--ink);margin-top:2px}
.solo-ratio-desc{position:relative;z-index:1;font-size:12.5px;color:var(--muted);margin-top:2px}
.solo-ratio-player{width:100%;display:flex;align-items:center;gap:10px;margin-top:22px;padding:10px 14px;background:#ffffffb3;border:1px solid var(--line);border-radius:12px}
.solo-ratio-play{flex:0 0 auto;display:flex;align-items:center;justify-content:center;width:36px;height:36px;min-width:36px;min-height:36px;border-radius:50%;background:#1c2022;color:#fff}
.solo-ratio-play:disabled{opacity:.4}
.solo-ratio-play .icon-pause[hidden]{display:none}
.solo-ratio-progress{flex:1 1 auto;display:flex;align-items:center;gap:8px;min-width:0}
.solo-ratio-time{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums;flex:0 0 auto}
.solo-ratio-bar{position:relative;flex:1 1 auto;height:4px;border-radius:2px;background:#dfe2e3;cursor:pointer}
.solo-ratio-bar-fill{position:absolute;left:0;top:0;height:100%;width:0;border-radius:2px;background:linear-gradient(90deg,#8b9296,#1c2022)}
.solo-ratio-mute{flex:0 0 auto;display:flex;align-items:center;justify-content:center;width:32px;height:32px;min-width:32px;min-height:32px;color:var(--muted)}
.solo-ratio-mute.is-muted{color:var(--ink)}
.solo-ratio-mute .mute-wave{transition:opacity .15s}
.solo-ratio-mute.is-muted .mute-wave{opacity:.25}
.solo-ratio-slider-wrap{position:relative;width:100%;margin-top:30px;padding-top:26px}
.solo-ratio-bubble{position:absolute;top:0;left:66.666%;transform:translateX(-50%);font-size:10.5px;font-weight:600;letter-spacing:.02em;padding:4px 10px;border-radius:999px;background:#eceeee;color:#7a8286;border:1px solid #d8dbdc;white-space:nowrap;transition:background-color .2s,color .2s,border-color .2s}
.solo-ratio-bubble:after{content:"";position:absolute;left:50%;bottom:-4px;width:7px;height:7px;transform:translateX(-50%) rotate(45deg);background:inherit;border-right:1px solid #d8dbdc;border-bottom:1px solid #d8dbdc}
.solo-ratio-bubble.is-active{background:#1c2022;color:#fff;border-color:#1c2022}
.solo-ratio-bubble.is-active:after{border-color:#1c2022}
.solo-ratio-slider{appearance:none;-webkit-appearance:none;width:100%;height:4px;border-radius:2px;background:linear-gradient(to right,#8b9296 calc(var(--solo-ratio-fill,0%)),#dfe2e3 calc(var(--solo-ratio-fill,0%)));outline:none;margin:0}
.solo-ratio-slider:disabled{opacity:.5}
.solo-ratio-slider::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ffffff,#c7cbcd 55%,#9aa0a3 100%);border:1px solid #b9bec0;box-shadow:0 2px 5px #1c232833;cursor:pointer;transition:transform .18s ease-out}
.solo-ratio-slider::-webkit-slider-thumb:active{transform:scale(1.08)}
