/* == css/ar-ratio-cd.css == */
/* AR RATIO EXPERIENCE — 레트로 턴테이블 버전 (2026-09-24)
   색은 상세페이지 무채색 토큰만 사용한다. 배경은 좌→우 흰색→옅은 회색. */
.wistia-ar,.wistia-ar *{box-sizing:border-box}
.solo-detail-scope>.wistia-ar,.wistia-ar{--ar-ink:#202426;--ar-muted:#737b7f;--ar-soft:#8c9497;--ar-line:#d5d9db;--wistia-ratio-progress:57.14;position:relative;isolation:isolate;width:100%;overflow:hidden;color:var(--ar-ink);background:linear-gradient(90deg,#ffffff 0%,#f7f8f8 42%,#e7e9ea 100%);font-family:"Pretendard Variable",Pretendard,'Noto Sans KR','Apple SD Gothic Neo',Arial,sans-serif}
.wistia-ar__artboard{width:100%;max-width:460px;margin:0 auto;padding:44px var(--solo-page-gutter,24px) 40px}

/* 타이틀 — AR BENEFIT 인트로와 같은 타이포 토큰(solo-typography.css)을 그대로 쓰고 가운데 정렬만 지정 */
.wistia-ar__copy{text-align:center}
.solo-detail-scope .wistia-ar__copy [data-solo-kicker],.solo-detail-scope .wistia-ar__copy [data-solo-title],.solo-detail-scope .wistia-ar__copy [data-solo-sub]{text-align:center}
.solo-detail-scope .wistia-ar__emphasis{margin-top:0}
.solo-detail-scope .wistia-ar__title-line{margin-top:3px}
.solo-detail-scope .wistia-ar__copy[data-solo-section-intro] [data-solo-kicker]{margin-bottom:11px!important}
.solo-detail-scope .wistia-ar__copy[data-solo-section-intro] [data-solo-sub]{margin-top:13px!important}
.solo-detail-scope .wistia-ar__lead-line{white-space:nowrap;font-size:min(11.5px,3.3cqw);letter-spacing:-.025em!important}

/* 턴테이블 본체 */
.wistia-ar__disc-stage{position:relative;width:min(100%,340px);margin:30px auto 0;outline:0;cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}
.wistia-ar__disc-stage:focus-visible{outline:2px solid var(--ar-ink);outline-offset:6px;border-radius:24px}
.wistia-ar__deck{position:relative;width:100%;aspect-ratio:100/96;border-radius:7%/7.3%;background:repeating-linear-gradient(90deg,#ffffff00 0 2px,#ffffff14 2px 3px,#0000000a 3px 4px),linear-gradient(140deg,#dfe2e4 0%,#caced1 42%,#bec2c5 72%,#c9cdd0 100%);box-shadow:0 26px 38px -24px #1a1e2066,0 2px 4px #1a1e201f,inset 0 1px 0 #ffffffcc,inset 0 -2px 3px #0000001c}
.wistia-ar__brand{position:absolute;top:5.4%;left:6.2%;color:#9ba0a3;font-size:9px;font-weight:700;letter-spacing:.32em;text-shadow:0 1px 0 #ffffffb3}
.wistia-ar__speed{position:absolute;right:6.4%;bottom:27%;color:#9ba0a3;font-size:8px;font-weight:700;letter-spacing:.08em;text-shadow:0 1px 0 #ffffffb3}
.wistia-ar__speed i{margin:0 2px;font-style:normal}

.wistia-ar__platter{position:absolute;left:6%;top:9.4%;width:78%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle closest-side,#18191a 0 90%,#3d4144 91%,#8f9497 93.5%,#d3d7d9 97%,#8a8f92 100%);box-shadow:0 12px 20px -12px #0000008c,0 1px 0 #ffffff99,inset 0 0 0 1px #00000040}
.wistia-ar__record{position:absolute;inset:4.5%;border-radius:50%;animation:wistia-ar-spin 1.8s linear infinite;animation-play-state:paused;will-change:transform}
.wistia-ar.is-playing .wistia-ar__record{animation-play-state:running}
.wistia-ar__vinyl{display:block;width:100%;height:100%;object-fit:contain;transform:scale(1.06);pointer-events:none}
.wistia-ar__label{position:absolute;inset:34%;display:grid;place-items:center;border-radius:50%;background:radial-gradient(circle,#f6f5f1 0 58%,#e8e6e0 100%);box-shadow:inset 0 0 0 1px #00000014,0 0 0 1px #00000059}
.wistia-ar__label img{width:64%;height:auto;opacity:.92;pointer-events:none}
/* AR 비율만큼 넓어지는 은은한 링 — 비율이 커질수록 LP 위의 AR 영역이 커진다 */
.wistia-ar__ar-ring{position:absolute;top:50%;left:50%;width:calc(38% + var(--wistia-ratio-progress)*.54%);aspect-ratio:1;border:1px solid #ffffff5c;border-radius:50%;background:radial-gradient(circle closest-side,#ffffff00 70%,#ffffff14 100%);transform:translate(-50%,-50%);pointer-events:none;transition:width .35s cubic-bezier(.2,.7,.2,1)}
.wistia-ar__spindle{position:absolute;top:50%;left:50%;width:3.4%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ffffff,#9ea3a6 60%,#5d6265);transform:translate(-50%,-50%)}
@keyframes wistia-ar-spin{to{transform:rotate(360deg)}}

.wistia-ar__tonearm{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;filter:drop-shadow(0 3px 2px #0000003d)}
.wistia-ar__arm{transform-box:view-box;transform-origin:86px 13px;transform:rotate(-4deg);transition:transform .75s cubic-bezier(.3,.7,.2,1)}
.wistia-ar.is-playing .wistia-ar__arm{transform:rotate(10deg)}

.wistia-ar__lever{position:absolute;left:6.4%;bottom:7%;width:8px;height:12%;border-radius:4px;background:#2a2d2f;box-shadow:inset 0 1px 2px #000000a6,0 1px 0 #ffffffa6}
.wistia-ar__lever i{position:absolute;left:50%;bottom:5%;width:12px;height:42%;border-radius:3px;background:linear-gradient(90deg,#2b2e30,#565a5d 45%,#1e2022);box-shadow:0 2px 3px #00000059;transform:translateX(-50%);transition:bottom .35s ease}
.wistia-ar.is-playing .wistia-ar__lever i{bottom:53%}
.wistia-ar__lever-label{position:absolute;left:10.4%;bottom:6.2%;display:grid;gap:10px;color:#9ba0a3;font-size:7px;font-weight:700;letter-spacing:.08em;text-shadow:0 1px 0 #ffffffb3}
.wistia-ar__lever-label b{font-weight:inherit}
.wistia-ar__lever-label b:first-child{order:2}
.wistia-ar__switch{position:absolute;right:6.8%;bottom:7%;width:10px;height:14%;border-radius:3px;background:#9ea3a6;box-shadow:inset 0 1px 3px #0000005c,0 1px 0 #ffffffa6}
.wistia-ar__switch i{position:absolute;left:50%;top:calc(6% + (100 - var(--wistia-ratio-progress))*.52%);width:12px;height:38%;border-radius:2px;background:linear-gradient(180deg,#3a3e40,#1d1f21);transform:translateX(-50%);box-shadow:0 1px 2px #00000066;transition:top .35s ease}

/* 스와이프 코치마크 — 비율 바 위에서 손가락이 점선을 따라 좌우로 오가며 "여기를 움직이세요"를 알려준다, 첫 조작 후 사라짐 */
.wistia-ar__coach{position:absolute;left:24%;right:24%;top:50%;z-index:3;height:0;pointer-events:none;transition:opacity .35s ease}
.wistia-ar__coach-path{position:absolute;left:0;right:0;top:0;border-top:1.5px dashed #20242680}
.wistia-ar__coach-path:before,.wistia-ar__coach-path:after{content:"";position:absolute;top:-4.5px;width:7px;height:7px;border-top:1.5px solid #20242699;border-left:1.5px solid #20242699}
.wistia-ar__coach-path:before{left:0;transform:rotate(-45deg)}
.wistia-ar__coach-path:after{right:0;transform:rotate(135deg)}
.wistia-ar__coach-hand{position:absolute;left:50%;top:-3px;width:30px;height:30px;margin-left:-12px;fill:#fff;stroke:#202426;stroke-width:1.3;stroke-linejoin:round;filter:drop-shadow(0 2px 3px #0000004d);animation:wistia-ar-swipe 2.6s ease-in-out infinite}
.wistia-ar.is-touched .wistia-ar__coach{opacity:0}
@keyframes wistia-ar-swipe{0%,100%{transform:translateX(0)}25%{transform:translateX(-46px)}75%{transform:translateX(46px)}}

/* 얇은 플레이바 */
.wistia-ar__player{position:relative;display:grid;grid-template-columns:30px auto minmax(0,1fr) auto 22px;align-items:center;gap:10px;width:min(100%,340px);margin:22px auto 0}
.wistia-ar__play{display:grid;place-items:center;width:30px;height:30px;padding:0;border:1px solid var(--ar-ink);border-radius:50%;background:transparent;color:var(--ar-ink);cursor:pointer;transition:background .2s ease,color .2s ease}
.wistia-ar__play:hover{background:var(--ar-ink);color:#fff}
.wistia-ar__play-icon{width:0;height:0;margin-left:2px;border-top:5px solid transparent;border-bottom:5px solid transparent;border-left:8px solid currentColor}
.wistia-ar__play[aria-pressed=true] .wistia-ar__play-icon{width:8px;height:10px;margin:0;border:0;background:linear-gradient(90deg,currentColor 0 34%,transparent 34% 66%,currentColor 66%)}
.wistia-ar__time{color:var(--ar-muted);font-size:11px;font-variant-numeric:tabular-nums;letter-spacing:0;white-space:nowrap}
.wistia-ar__seek{width:100%;min-width:0;height:18px;margin:0;appearance:none;-webkit-appearance:none;background:transparent;cursor:pointer}
.wistia-ar__seek::-webkit-slider-runnable-track{height:2px;border-radius:2px;background:linear-gradient(90deg,var(--ar-ink) var(--wistia-progress,0%),var(--ar-line) var(--wistia-progress,0%))}
.wistia-ar__seek::-webkit-slider-thumb{width:10px;height:10px;margin-top:-4px;appearance:none;-webkit-appearance:none;border:0;border-radius:50%;background:var(--ar-ink)}
.wistia-ar__seek::-moz-range-track{height:2px;border-radius:2px;background:var(--ar-line)}
.wistia-ar__seek::-moz-range-progress{height:2px;border-radius:2px;background:var(--ar-ink)}
.wistia-ar__seek::-moz-range-thumb{width:10px;height:10px;border:0;border-radius:50%;background:var(--ar-ink)}
.wistia-ar__volume{display:grid;place-items:center;width:22px;height:22px;padding:0;border:0;background:transparent;color:var(--ar-muted);cursor:pointer}
.wistia-ar__volume svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.wistia-ar__vol-body{fill:currentColor}
.wistia-ar__vol-mute,.wistia-ar__volume.is-muted .wistia-ar__vol-wave{display:none}
.wistia-ar__volume.is-muted .wistia-ar__vol-mute{display:inline}
.wistia-ar__error{position:absolute;top:calc(100% + 4px);left:40px;margin:0;color:#a33f3f;font-size:11px}
.wistia-ar__error[hidden],.wistia-ar__audio{display:none}

/* LIVE/AR 비율 바 — 두툼한 무광 트랙 + 흰 원형 손잡이 */
.wistia-ar__ratio{width:min(100%,340px);margin:26px auto 0}
.wistia-ar__ratio-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}
.wistia-ar__mood-wrap{display:inline-flex;align-items:center;gap:8px}
/* 마우스 휠 힌트 — 휠이 아래로 굴러가는 작은 마우스 아이콘 */
.wistia-ar__scroll-hint{position:relative;display:none;width:12px;height:18px;border:1.3px solid var(--ar-soft);border-radius:7px}
.wistia-ar__scroll-hint i{position:absolute;top:3px;left:50%;width:2px;height:4px;margin-left:-1px;border-radius:1px;background:var(--ar-ink);animation:wistia-ar-wheel 1.5s ease-in-out infinite}
@keyframes wistia-ar-wheel{0%{transform:translateY(0);opacity:0}25%{opacity:1}70%{transform:translateY(6px);opacity:0}100%{opacity:0}}
@media(hover:hover) and (pointer:fine){.wistia-ar__scroll-hint{display:inline-block}.wistia-ar__ratio{cursor:ns-resize}.wistia-ar__ratio-input{cursor:pointer}}
.wistia-ar__play[aria-busy=true]{opacity:.55}
.wistia-ar__mood{color:var(--ar-muted);font-size:12px;font-weight:500;letter-spacing:-.015em}
.wistia-ar__ratio-current{color:var(--ar-ink);font-size:22px;font-weight:500;font-variant-numeric:tabular-nums;letter-spacing:-.04em;line-height:1}
.wistia-ar__ratio-current:before{content:"AR ";color:var(--ar-soft);font-size:10px;font-weight:700;letter-spacing:.16em;vertical-align:3px}
.wistia-ar__ratio-field{position:relative;height:46px;border-radius:999px;background:linear-gradient(90deg,#d6dadc 0,#d6dadc calc(19px + (100% - 38px)*var(--wistia-ratio-progress)/100),#eceeef calc(19px + (100% - 38px)*var(--wistia-ratio-progress)/100),#eceeef 100%);box-shadow:inset 0 1px 3px #1a1e2017,inset 0 0 0 1px #1a1e200a}
.wistia-ar__ratio-end{position:absolute;top:50%;z-index:1;color:#8c9497;font-size:9.5px;font-weight:700;letter-spacing:.16em;transform:translateY(-50%);pointer-events:none}
.wistia-ar__ratio-end--live{left:17px}
.wistia-ar__ratio-end--ar{right:17px}
.wistia-ar__ratio-input{position:absolute;inset:0;z-index:2;width:100%;height:46px;margin:0;appearance:none;-webkit-appearance:none;background:transparent;cursor:pointer}
.wistia-ar__ratio-input::-webkit-slider-runnable-track{height:46px;border-radius:999px;background:transparent}
.wistia-ar__ratio-input::-webkit-slider-thumb{width:38px;height:38px;margin-top:4px;appearance:none;-webkit-appearance:none;border:0;border-radius:50%;background:#fff;box-shadow:0 2px 6px #1a1e2029,0 0 0 1px #1a1e200d}
.wistia-ar__ratio-input::-moz-range-track{height:46px;background:transparent}
.wistia-ar__ratio-input::-moz-range-thumb{width:38px;height:38px;border:0;border-radius:50%;background:#fff;box-shadow:0 2px 6px #1a1e2029,0 0 0 1px #1a1e200d}
.wistia-ar__ratio-marks{position:relative;height:16px;margin-top:12px;color:var(--ar-soft);font-size:11px;font-variant-numeric:tabular-nums}
.wistia-ar__ratio-marks span{position:absolute;top:0;transform:translateX(-50%);transition:color .25s ease}
.wistia-ar__ratio-marks span[data-value="30"]{left:19px}
.wistia-ar__ratio-marks span[data-value="50"]{left:calc(19px + (100% - 38px)*.2857)}
.wistia-ar__ratio-marks span[data-value="70"]{left:calc(19px + (100% - 38px)*.5714)}
.wistia-ar__ratio-marks span[data-value="100"]{left:calc(100% - 19px)}
.wistia-ar__ratio-marks span.is-active{color:var(--ar-ink);font-weight:600}

.wistia-ar button:focus-visible,.wistia-ar input:focus-visible{outline:2px solid var(--ar-ink);outline-offset:4px}
.wistia-ar__ratio-input:focus-visible{outline-offset:2px;border-radius:999px}

@container solo-detail (max-width:360px){
 .wistia-ar__artboard{padding:38px 20px 36px}
 .wistia-ar__disc-stage{margin-top:24px}
 .wistia-ar__player{gap:8px}
}
@media(prefers-reduced-motion:reduce){.wistia-ar *,.wistia-ar *:before,.wistia-ar *:after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}}
/* == css/process-studio.css == */
.wistia-process-studio {
  --wps-ink: #181817;
  --wps-muted: #77736d;
  --wps-line: #d8d3cb;
  --wps-paper: #f3f4f4;
  --wps-white: #fff;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  overflow: hidden;
  padding: 56px 22px 34px;
  color: var(--wps-ink);
  background: var(--wps-paper);
  background-image: none;
}

.solo-detail-scope .wistia-process-studio {
  background-color: var(--wps-paper);
  background-image: none;
}

.wistia-process-studio *,
.wistia-process-studio *::before,
.wistia-process-studio *::after {
  box-sizing: border-box;
}

.wistia-process-studio .wps-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin: 0 0 28px;
}

.wistia-process-studio .wps-kicker,
.wistia-process-studio .wps-step {
  margin: 0;
  color: var(--wps-muted);
  font-size: 9px;
  font-weight: 700;
  line-height: 1.4;
  letter-spacing: .17em;
}

.wistia-process-studio .wps-head h2 {
  margin: 10px 0 0;
  max-width: 330px;
  font-size: clamp(25px, 6.2vw, 31px);
  font-weight: 400;
  line-height: 1.16;
  letter-spacing: -.045em;
}

.wistia-process-studio .wps-head h2 strong {
  font-weight: 760;
}

.wistia-process-studio .wps-counter {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  padding-bottom: 3px;
  color: #9c978f;
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  letter-spacing: .08em;
}

.wistia-process-studio .wps-counter [data-process-current] {
  color: var(--wps-ink);
  font-weight: 750;
}

.wistia-process-studio .wps-counter i {
  width: 28px;
  height: 1px;
  background: var(--wps-line);
}

.wistia-process-studio .wps-feature {
  display: grid;
  grid-template-columns: 59% 41%;
  width: 100%;
  height: 356px;
  min-width: 0;
  overflow: hidden;
  outline: none;
  background: var(--wps-white);
  border: 1px solid #ded9d2;
  box-shadow: 0 18px 38px rgb(36 31 24 / 10%);
}

.wistia-process-studio .wps-feature:focus-visible {
  outline: 2px solid var(--wps-ink);
  outline-offset: 3px;
}

.wistia-process-studio .wps-photo {
  position: relative;
  min-width: 0;
  height: 100%;
  overflow: hidden;
  background: #ddd8d0;
}

.wistia-process-studio .wps-photo img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.wistia-process-studio .wps-badge {
  position: absolute;
  z-index: 1;
  top: 17px;
  left: 17px;
  padding: 6px 8px;
  border-radius: 18px;
  color: #fff;
  background: rgb(18 18 17 / 88%);
  font-size: 7px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: .12em;
}

.wistia-process-studio .wps-content {
  position: relative;
  display: flex;
  min-width: 0;
  height: 100%;
  flex-direction: column;
  overflow: hidden;
  padding: 30px 22px 20px;
  background: #fff;
}

.wistia-process-studio .wps-ghost {
  position: absolute;
  top: 6px;
  right: 8px;
  color: #f0ede8;
  font-size: 64px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -.08em;
  pointer-events: none;
}

.wistia-process-studio .wps-step {
  position: relative;
  z-index: 1;
  margin-top: 34px;
}

.wistia-process-studio .wps-content h3 {
  position: relative;
  z-index: 1;
  margin: 10px 0 12px;
  font-size: clamp(19px, 4.6vw, 23px);
  font-weight: 730;
  line-height: 1.18;
  letter-spacing: -.045em;
}

.wistia-process-studio .wps-description {
  position: relative;
  z-index: 1;
  margin: 0;
  color: #6e6a65;
  font-size: 10px;
  line-height: 1.72;
  word-break: keep-all;
}

.wistia-process-studio .wps-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin: auto 0 16px;
  padding-top: 14px;
  border-top: 1px solid #e5e1db;
}

.wistia-process-studio .wps-detail span {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
  color: var(--wps-ink);
  font-size: 9px;
  line-height: 1.35;
}

.wistia-process-studio .wps-detail strong {
  color: #9c978f;
  font-size: 7px;
  font-weight: 600;
  letter-spacing: .04em;
}

.wistia-process-studio .wps-controls {
  display: flex;
  gap: 7px;
}

.wistia-process-studio .wps-controls button {
  display: grid;
  width: 34px;
  height: 34px;
  padding: 0;
  place-items: center;
  border: 1px solid #cec9c1;
  border-radius: 50%;
  color: var(--wps-ink);
  background: #fff;
  font: inherit;
  cursor: pointer;
  transition: color 180ms ease, background-color 180ms ease, border-color 180ms ease, opacity 180ms ease;
}

.wistia-process-studio .wps-controls button.is-next {
  color: #fff;
  border-color: var(--wps-ink);
  background: var(--wps-ink);
}

.wistia-process-studio .wps-controls button.is-toggle {
  font-size: 10px;
  font-weight: 750;
  letter-spacing: -.08em;
}

.wistia-process-studio .wps-chapters[hidden] {
  display: none !important;
}

.wistia-process-studio .wps-controls button:disabled {
  opacity: .28;
  cursor: default;
}

.wistia-process-studio .wps-chapters {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  width: 100%;
  min-width: 0;
  margin: 12px 0 0;
  overflow: hidden;
  border: 1px solid #d7d2cb;
  background: #ebe7e1;
}

.wistia-process-studio .wps-chapter {
  display: flex;
  min-width: 0;
  height: 68px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  padding: 10px 7px 9px;
  border: 0;
  border-right: 1px solid #d7d2cb;
  color: #918c85;
  background: transparent;
  text-align: left;
  cursor: pointer;
  transition: color 220ms ease, background-color 220ms ease;
}

.wistia-process-studio .wps-chapter:last-child {
  border-right: 0;
}

.wistia-process-studio .wps-chapter b {
  font-size: 9px;
  font-weight: 650;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.wistia-process-studio .wps-chapter span {
  display: block;
  overflow: hidden;
  font-size: 7px;
  font-weight: 620;
  line-height: 1.25;
  letter-spacing: -.025em;
  text-overflow: ellipsis;
}

.wistia-process-studio .wps-chapter.is-active {
  color: #fff;
  background: var(--wps-ink);
}

.wistia-process-studio .wps-feature.is-entering .wps-photo img {
  animation: wps-photo-in 720ms cubic-bezier(.16,1,.3,1) both;
}

.wistia-process-studio .wps-feature.is-entering .wps-content > :not(.wps-ghost) {
  animation: wps-copy-in 620ms 80ms cubic-bezier(.16,1,.3,1) both;
}

@keyframes wps-photo-in {
  from { opacity: .42; transform: scale(1.025); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes wps-copy-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (hover: hover) {
  .wistia-process-studio .wps-controls button:not(:disabled):hover {
    color: #fff;
    border-color: var(--wps-ink);
    background: var(--wps-ink);
  }

  .wistia-process-studio .wps-chapter:not(.is-active):hover {
    color: var(--wps-ink);
    background: #f6f3ee;
  }
}

@media (max-width: 430px) {
  .wistia-process-studio {
    padding: 48px 18px 28px;
  }

  .wistia-process-studio .wps-head {
    align-items: flex-start;
    margin-bottom: 22px;
  }

  .wistia-process-studio .wps-head h2 {
    max-width: 280px;
    font-size: 27px;
  }

  .wistia-process-studio .wps-counter {
    padding-top: 3px;
  }

  .wistia-process-studio .wps-counter i {
    width: 16px;
  }

  .wistia-process-studio .wps-feature {
    display: flex;
    height: auto;
    flex-direction: column;
  }

  .wistia-process-studio .wps-photo {
    flex: 0 0 auto;
    width: 100%;
    height: 236px;
  }

  .wistia-process-studio .wps-content {
    width: 100%;
    min-height: 294px;
    padding: 25px 22px 20px;
  }

  .wistia-process-studio .wps-step {
    margin-top: 28px;
  }

  .wistia-process-studio .wps-content h3 {
    font-size: 23px;
  }

  .wistia-process-studio .wps-description {
    max-width: 300px;
    font-size: 11px;
  }

  .wistia-process-studio .wps-chapters {
    display: flex;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-inline: contain;
    scroll-snap-type: x proximity;
    scrollbar-width: none;
  }

  .wistia-process-studio .wps-chapters::-webkit-scrollbar {
    display: none;
  }

  .wistia-process-studio .wps-chapter {
    min-width: 112px;
    height: 70px;
    flex: 0 0 112px;
    scroll-snap-align: center;
    padding-inline: 11px;
  }

  .wistia-process-studio .wps-chapter span {
    font-size: 9px;
  }
}

@media (max-width: 370px) {
  .wistia-process-studio {
    padding-inline: 15px;
  }

  .wistia-process-studio .wps-head h2 {
    font-size: 25px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .wistia-process-studio .wps-feature.is-entering .wps-photo img,
  .wistia-process-studio .wps-feature.is-entering .wps-content > :not(.wps-ghost) {
    animation: none;
  }

  .wistia-process-studio .wps-controls button,
  .wistia-process-studio .wps-chapter {
    transition: none;
  }
}
/* == css/hero-editor.css == */
.hero-editor-launch{position:relative;z-index:1;display:block;width:min(1240px,calc(100% - 96px));margin:22px auto 0;padding:9px 0;font-size:12px;color:#56656c;text-align:right;text-decoration:underline;text-underline-offset:5px}
.hero-editor{width:min(1360px,calc(100% - 48px));margin:30px auto 100px;color:#283134}
.hero-editor-bar{position:sticky;top:var(--header);z-index:42;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:15px 20px;background:#fff;border:1px solid #cbd4d7;box-shadow:0 8px 22px #1f292d13}
.hero-editor-bar>div:first-child{display:grid;gap:2px}.hero-editor-bar strong{font-size:15px;font-weight:600}.hero-editor-bar span{font-size:11px;color:#738087}
.hero-editor-actions{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.hero-editor-actions button,.hero-editor-actions a{min-height:36px;padding:8px 12px;background:#f0f3f4;font-size:12px;color:#293335}.hero-editor-actions a{background:#293335;color:#fff}
.hero-editor-help{margin:13px 0 18px;font-size:12px;color:#647279}
.hero-editor-scroll{overflow-x:auto;border:1px solid #cbd4d7;background:#f1f3f4}
.hero-editor-canvas{position:relative;min-width:900px;width:100%;height:660px;overflow:hidden;background:#f7f8f8}
.hero-edit-block{position:absolute;min-width:45px;min-height:35px;outline:1px dashed transparent;cursor:pointer}
.hero-edit-block:hover,.hero-edit-block.is-selected{outline:2px solid #386a91;outline-offset:2px}
.hero-edit-content{width:100%;height:100%;overflow:hidden;white-space:pre-wrap;outline:0}
.hero-edit-content[contenteditable=true]{background:#ffffffd9;box-shadow:inset 0 0 0 1px #386a91;cursor:text}
.hero-edit-title .hero-edit-content{font-size:clamp(42px,5vw,78px);font-weight:500;line-height:1.35;letter-spacing:-.045em;color:#25292b}
.hero-edit-intro .hero-edit-content{font-size:clamp(20px,2.25vw,32px);line-height:1.65;color:#5e696f}
.hero-edit-fact .hero-edit-content{font-size:17px;line-height:1.9;color:#5e696f}
.hero-edit-result .hero-edit-content{font-size:clamp(22px,2.4vw,34px);line-height:1.45;color:#283134}
.hero-edit-copy .hero-edit-content{font-size:clamp(16px,1.5vw,21px);line-height:1.6;color:#5e696f}
.hero-edit-video .hero-edit-content{position:relative;background:#dce5e9}
.hero-edit-video img{width:100%;height:100%;object-fit:cover;pointer-events:none}
.hero-edit-play{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:grid;place-items:center;width:68px;height:68px;padding-left:4px;border-radius:50%;background:#fffffff0;color:#273134;font-size:22px}
.hero-edit-controls{position:absolute;left:0;top:-38px;display:none;align-items:center;gap:2px;white-space:nowrap;z-index:2}.hero-edit-block.is-selected .hero-edit-controls{display:flex}
.hero-edit-controls button{padding:6px 9px;min-height:30px;background:#293335;color:#fff;font-size:11px}.hero-edit-controls button:hover{background:#405157}
.hero-edit-move{cursor:grab;touch-action:none}.hero-edit-move:active{cursor:grabbing}
.hero-edit-resize{position:absolute;right:-11px;bottom:-11px;display:none;width:27px;height:27px;background:#293335;color:white;font-size:16px;cursor:nwse-resize;touch-action:none}.hero-edit-block.is-selected .hero-edit-resize{display:block}
.hero-editor-bottom{display:flex;align-items:center;gap:18px;padding:18px 3px;font-size:12px;color:#67747a}.hero-editor-bottom>span{font-weight:600;color:#273134}.hero-editor-bottom>div{display:flex;gap:7px;flex-wrap:wrap}.hero-editor-bottom button{padding:6px 10px;border:1px solid #cbd4d7;font-size:11px}
.hero-editor.is-preview .hero-edit-block{outline:0}.hero-editor.is-preview .hero-edit-controls,.hero-editor.is-preview .hero-edit-resize{display:none!important}
.is-hero-editing .fixed-price{display:none}
@media(max-width:779px){.hero-editor-launch{width:calc(100% - 48px)}.hero-editor{width:calc(100% - 24px)}.hero-editor-bar{position:static;display:grid;padding:12px}.hero-editor-actions{gap:5px}.hero-editor-actions button,.hero-editor-actions a{font-size:11px}.hero-editor-canvas{width:900px}.hero-editor-help{font-size:11px}}
/* == css/process-editor.css == */
.is-process-editing #process{position:relative}
#processEditorBar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;width:min(1240px,calc(100% - 48px));margin:30px auto 0;padding:12px 16px;border:1px solid #cbd4d7;background:#fff;color:#283134;font-size:12px}
#processEditorBar strong{font-size:14px}
#processEditorBar span{color:#66747a}
#processEditorBar button{padding:6px 9px;border:1px solid #cbd4d7;font-size:11px}
#processEditorRestore{display:flex;gap:5px;flex-wrap:wrap;margin-left:auto}
.is-process-editing .process-edit-target{outline:1px dashed transparent;outline-offset:3px;cursor:pointer}
.is-process-editing .process-edit-target:hover,.is-process-editing .process-edit-target.is-process-selected{outline:2px solid #386a91}
.is-process-editing .process-edit-target[contenteditable=true]{background:#eef6fa;outline:2px solid #386a91;cursor:text}
