/* == css/home-finder.css == */
.finder-home{position:relative;isolation:isolate;max-width:1040px;padding-top:clamp(52px,9vw,118px);padding-bottom:120px;text-align:center;overflow:hidden}
.finder-stage-role:before{content:"";position:absolute;z-index:-1;left:50%;bottom:-36%;width:145%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 50% 24%,#f8f9f9 0,#eceeef 34%,#d9dddf 58%,rgba(217,221,223,0) 72%);opacity:.78;transform:translate(-50%,45%);pointer-events:none}
.finder-home .sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
.finder-back{display:table;margin:0 auto 28px;color:#5c6a71;font-size:14px;text-decoration:underline;text-underline-offset:5px}
.finder-intro{max-width:1000px;margin:0 auto 68px}
.finder-intro .eyebrow{font-size:12px;letter-spacing:.22em;color:#68787e}
.finder-intro h1{max-width:100%;margin:19px auto 22px;font-size:clamp(34px,5.2vw,54px);line-height:1.18;font-weight:500;letter-spacing:-.055em;color:#273034;text-wrap:balance;word-break:keep-all}
.finder-intro p{font-size:clamp(16px,1.55vw,21px);line-height:1.7;color:#617077}
.finder-steps{display:grid;gap:64px}
.finder-step{min-width:0;margin:0;padding:0;border:0}
.finder-step[hidden],.finder-result[hidden]{display:none}
.finder-step legend{display:flex;align-items:baseline;gap:17px;width:100%;margin-bottom:22px;font-size:clamp(24px,2.7vw,36px);font-weight:500;letter-spacing:-.04em;color:#273034}
.finder-step legend span{font-size:13px;letter-spacing:.08em;color:#819096}
.finder-options{display:grid;grid-template-columns:1fr;gap:14px;width:min(100%,680px);margin-inline:auto}
.finder-choice{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;min-height:132px;padding:26px 28px;border:1px solid #d3dce0;background:#fff;text-align:center;cursor:pointer;transition:background .2s,border-color .2s}
.finder-choice:hover{border-color:#83949b;background:#f8fafb}
.finder-choice input{position:absolute;inset:0;opacity:0;cursor:pointer}
.finder-choice:has(input:checked){border:2px solid #34464d;background:#f5f8f9;padding:25px 27px}
.finder-choice:has(input:focus-visible){outline:2px solid #345d77;outline-offset:3px}
.finder-choice-mark{flex:none;width:21px;height:21px;border:1px solid #809098;border-radius:50%}
.finder-choice:has(input:checked) .finder-choice-mark{border:6px solid #34464d}
.finder-choice>span:last-child{display:grid;justify-items:center;gap:9px}
.finder-choice strong{font-size:20px;line-height:1.4;font-weight:500;color:#273034}
.finder-choice small{font-size:14px;line-height:1.55;color:#637078}
.finder-service-badge{display:inline-flex;align-items:center;gap:7px;padding:7px 11px;border-radius:999px;background:#202628;color:#fff}
