/* == css/solo-typography.css == */
.solo-detail-scope {
  --solo-type-ink: #202426;
  --solo-type-muted: #737b7f;
  --solo-type-kicker: #8c9497;
  --solo-type-title-size: 26px;
  --solo-type-sub-size: 11.5px;
}

.solo-detail-scope [data-solo-kicker],
.solo-detail-scope [data-solo-title],
.solo-detail-scope [data-solo-sub] {
  font-family: var(--sans);
  font-style: normal;
}

.solo-detail-scope [data-solo-kicker] {
  margin: 0 0 16px;
  color: var(--solo-type-kicker);
  font-size: 9px !important;
  font-weight: 750 !important;
  line-height: 1.4 !important;
  letter-spacing: .17em !important;
  text-transform: uppercase;
}

.solo-detail-scope [data-solo-title] {
  margin: 0;
  color: var(--solo-type-ink);
  font-size: var(--solo-type-title-size) !important;
  font-weight: 500 !important;
  line-height: 1.28 !important;
  letter-spacing: -.05em !important;
  word-break: keep-all;
}

.solo-detail-scope [data-solo-title] strong,
.solo-detail-scope [data-solo-title] b,
.solo-detail-scope [data-solo-title] .ar-copy-emphasis-text {
  font-weight: inherit;
}

.solo-detail-scope [data-solo-sub] {
  margin: 20px 0 0;
  color: var(--solo-type-muted);
  font-size: var(--solo-type-sub-size) !important;
  font-weight: 400 !important;
  line-height: 1.85 !important;
  letter-spacing: -.015em !important;
  word-break: keep-all;
}

