/* One unmistakable price CTA across every product detail page */
.solo-detail-scope .solo-inline-contact{
  position:relative;
  isolation:isolate;
  overflow:hidden;
  min-height:88px;
  padding:16px 24px;
  border:1px solid #e8c800;
  border-radius:18px;
  background:linear-gradient(165deg,#fff58a 0%,#fee500 43%,#f2cd00 100%);
  color:#202425;
  box-shadow:inset 0 2px 0 #fff9b8,inset 0 -5px 0 #dbb800,0 8px 0 #bd9f00,0 19px 28px #3c32002b;
  transition:transform .2s ease,box-shadow .2s ease,filter .2s ease;
}
.solo-detail-scope .solo-inline-contact::before{
  content:"";
  position:absolute;
  inset:0;
  z-index:0;
  background:radial-gradient(ellipse at 79% 17%,#fff8bc 0%,#fff8bc00 38%);
  pointer-events:none;
}
.solo-detail-scope .solo-inline-contact::after{
  content:"";
  position:absolute;
  top:50%;
  right:46px;
  z-index:2;
  width:5px;
  height:5px;
  border-radius:50%;
  background:#fffefa;
  box-shadow:-30px -22px 0 0 #fffefa,-8px -37px 0 -1px #7f6800,19px -31px 0 -1px #fffefa,34px -8px 0 0 #fff6a4,30px 25px 0 -1px #806700,3px 37px 0 0 #fffefa,-27px 27px 0 -1px #fff7b9,-39px 1px 0 0 #806700;
  opacity:0;
  pointer-events:none;
  animation:price-cta-particles 3.2s ease-out infinite;
}
.solo-detail-scope .solo-inline-contact strong{position:relative;z-index:1;font-size:18px;font-weight:750;letter-spacing:-.04em;text-shadow:0 1px 0 #fff9a8}
.solo-detail-scope .solo-inline-contact span{
  display:grid;
  position:relative;
  z-index:1;
  flex:none;
  place-items:center;
  width:46px;
  height:46px;
  border:1px solid #4b4e46;
  border-radius:50%;
  background:linear-gradient(145deg,#41494a,#151819);
  color:#fff;
  font-size:28px;
  line-height:1;
  box-shadow:inset 0 1px 1px #ffffff6b,0 5px 0 #101414,0 9px 14px #4c3e0057;
  transform:translateY(-2px);
  transition:transform .2s ease,box-shadow .2s ease;
}
.solo-detail-scope .solo-inline-contact:hover,
.solo-detail-scope .solo-inline-contact:focus-visible{background:linear-gradient(165deg,#fff58a 0%,#fee500 43%,#f2cd00 100%);filter:saturate(1.1);transform:translateY(-2px)}
.solo-detail-scope .solo-inline-contact:active{transform:translateY(4px);box-shadow:inset 0 2px 0 #fff9b8,inset 0 -3px 0 #dbb800,0 3px 0 #bd9f00,0 8px 14px #3c320029}
.solo-detail-scope .solo-inline-contact:active span{transform:translateY(2px);box-shadow:inset 0 1px 1px #ffffff6b,0 1px 0 #101414}
@keyframes price-cta-particles{
  0%,65%,100%{opacity:0;transform:translateY(-50%) scale(.35) rotate(-15deg)}
  70%{opacity:1}
  86%{opacity:.9;transform:translateY(-50%) scale(1.15) rotate(8deg)}
  96%{opacity:0;transform:translateY(-50%) scale(1.45) rotate(15deg)}
}
@media(max-width:600px){
  .solo-detail-scope .worry-section{width:100%;margin-inline:0;padding-bottom:0}
  .solo-detail-scope .solo-inline-contact{
    width:calc(100% + 2 * var(--solo-page-gutter));
    min-height:92px;
    margin:28px calc(-1 * var(--solo-page-gutter)) 0;
    padding-inline:var(--solo-page-gutter);
    border-radius:0;
    box-shadow:inset 0 2px 0 #fff9b8,inset 0 -7px 0 #cdaa00;
  }
  .solo-detail-scope .solo-inline-contact strong{font-size:17px}
}
@media(prefers-reduced-motion:reduce){
  .solo-detail-scope .solo-inline-contact,
  .solo-detail-scope .solo-inline-contact span{transition:none}
  .solo-detail-scope .solo-inline-contact::after{animation:none;opacity:.65;transform:translateY(-50%) scale(.8)}
}

