}
@media(max-width:360px){.we-shell{width:calc(100% - 32px)}.we-hero h1{font-size:39px}.we-heading h2{font-size:30px}.arc-summary h1{font-size:21px}.arc-product{padding-inline:16px}.arc-price strong{font-size:31px}.arc-included{font-size:10px}.arc-hook{font-size:12px}.we-case-bar{font-size:9px}}
