#wistiaBeforeAfter .bap-tab{display:flex;flex-direction:column;justify-content:center;align-items:flex-start;gap:7px;min-height:90px;padding:17px 22px;border-radius:10px;border:1px solid #cbd4dc;background:#fff;color:#596b7b;transition:background .35s,color .35s,box-shadow .35s}
#wistiaBeforeAfter .bap-tab small{font-size:10px;letter-spacing:.14em;color:inherit;opacity:.7}
#wistiaBeforeAfter .bap-tab strong{font-size:20px;line-height:1.3;font-weight:600}
