.story-process-folder>summary:hover,.story-process-folder>summary:focus-visible{
 box-shadow:0 8px 24px #64798e1a,inset 0 0 0 1px #7892a6
}
.story-process-folder>summary:focus-visible{outline:2px solid #506f88;outline-offset:4px}
.process-folder-art{position:relative}
.folder-open-label{display:inline-flex;align-items:center;gap:10px}
