.process-folder-sparks{position:absolute;inset:-10px -6px;pointer-events:none}
.process-folder-sparks em{position:absolute;width:5px;height:5px;border-radius:50%;background:#7895ab;opacity:0}
.process-folder-sparks em:nth-child(1){top:8px;right:4px;--spark-delay:0s}
.process-folder-sparks em:nth-child(2){top:30px;right:-4px;--spark-delay:.18s}
