 html[data-studio-motion="on"] .story-process-folder:not([open]) .process-folder-sparks em{animation:folder-spark 2.8s ease-out var(--spark-delay) 3}
 html[data-studio-motion="on"] .story-process-folder:not(.is-cue-visible) .folder-cue-arrow,
 html[data-studio-motion="on"] .story-process-folder:not(.is-cue-visible) .process-folder-sparks em{animation-play-state:paused}
