}
@keyframes folder-cue-nudge{0%,65%,100%{transform:translateY(0)}76%{transform:translateY(4px)}88%{transform:translateY(0)}}
@keyframes folder-spark{0%,65%,100%{opacity:0;transform:translateY(5px) scale(.6)}76%{opacity:.8;transform:translateY(-3px) scale(1)}88%{opacity:0;transform:translateY(-10px) scale(.7)}}
