/* == css/monochrome-maru-theme.css == */
/* Approved 2026-10-05: fixed MaruBuri headings + Pretendard body/UI.
   Black identity/CTA, white reading canvas, gray supporting fields.
   Preserve layout, original media, the Kakao mark and all inquiry behaviour. */
html[data-wistia-theme="monochrome"],html[data-wistia-theme="monochrome"] body{
 --mono-black:#111111;--mono-white:#FFFFFF;--mono-gray:#E8E8E8;
 --font-body:"Pretendard Variable","Pretendard",sans-serif;
 --serif:var(--font-heading);--sans:var(--font-body);
 /* Compatibility aliases keep the approved rounded layout, not its old colours. */
 --dusty-pink:var(--mono-gray);--warm-beige:var(--mono-white);--warm-brown:var(--mono-black);--warm-ivory:var(--mono-white);--deep-brown:var(--mono-black);
 --brand-pink:var(--mono-gray);--brand-black:var(--mono-black);--brand-gray:var(--mono-gray);
 --brand-muted:rgba(17,17,17,.72);--brand-line:var(--mono-gray);
 --ink:var(--mono-black)!important;--muted:var(--brand-muted)!important;--line:var(--mono-gray)!important;
 --wash:var(--mono-gray)!important;--paper:var(--mono-white)!important;--white:var(--mono-white)!important;
 --soft:var(--mono-gray)!important;--silver:var(--brand-muted)!important;
 color:var(--mono-black);background:var(--mono-white)!important;accent-color:var(--mono-black);
}
/* The font families are locked independently of the colour theme. */
html[data-wistia-typography="maru-pretendard-fixed"] body,
html[data-wistia-typography="maru-pretendard-fixed"] :is(#app,#siteHeader,#mainMenu,#mediaDialog,#floatingKakao),
html[data-wistia-typography="maru-pretendard-fixed"] :is(#app,#siteHeader,#mainMenu,#mediaDialog,#floatingKakao) *{
 font-family:var(--font-body,"Pretendard Variable","Pretendard",sans-serif)!important;
}
html[data-wistia-typography="maru-pretendard-fixed"] :is(#app,#mediaDialog) :is(h1,h2,h3,h4,h5,h6),
html[data-wistia-typography="maru-pretendard-fixed"] :is(#app,#mediaDialog) :is(h1,h2,h3,h4,h5,h6) *,
html[data-wistia-typography="maru-pretendard-fixed"] :is(#siteHeader .wordmark>span,#app .mas-brand b,#app .footer-brand b){
 font-family:var(--font-heading)!important;
}
html[data-wistia-typography="maru-pretendard-fixed"] :is(#app,#mediaDialog,#siteHeader) :is(button,input,select,textarea,.button,.mas-bottom a,.inquiry-direct,.we-service-link,.wordmark small){
 font-family:var(--font-body,"Pretendard Variable","Pretendard",sans-serif)!important;
}
