/* == css/noir-minimal.css == */
/* Approved colour direction, 2026-10-06
   Charcoal #252421 / off-white #F5F4F0 / stone #DDDCD8
   Minimal modern/chic styling: retain content, genuine media and behaviour
   The monochrome attribute remains a compatibility hook for the approved layout */
html[data-wistia-palette="noir-minimal"],
html[data-wistia-palette="noir-minimal"] body{
 --palette-stone:#DDDCD8;--palette-charcoal:#252421;--palette-offwhite:#F5F4F0;
 --palette-ink:#252421;--palette-on-stone:#252421;--palette-paper:#FFFFFF;
 --palette-soft:#E9E8E4;--palette-selected:#D5D3CD;--palette-muted:#66645F;--palette-wave:#85827C;
 --palette-line:rgba(37,36,33,.20);--palette-control:#8B8880;
 --mono-black:var(--palette-ink);--mono-white:var(--palette-paper);--mono-gray:var(--palette-soft);
 --dusty-pink:var(--palette-soft);--warm-beige:var(--palette-offwhite);--warm-brown:var(--palette-ink);--warm-ivory:var(--palette-paper);--deep-brown:var(--palette-ink);
 --brand-pink:var(--palette-stone);--brand-black:var(--palette-ink);--brand-gray:var(--palette-offwhite);
 --brand-muted:var(--palette-muted);--brand-line:var(--palette-line);
 --ink:var(--palette-ink)!important;--muted:var(--palette-muted)!important;--line:var(--palette-line)!important;
 --wash:var(--palette-offwhite)!important;--paper:var(--palette-paper)!important;--white:var(--palette-paper)!important;
 --soft:var(--palette-soft)!important;--silver:var(--palette-muted)!important;
 color:var(--palette-ink);background:var(--palette-offwhite)!important;accent-color:var(--palette-charcoal);
}
/* Off-white reading canvas, charcoal hero/actions, quiet stone accents */
